from pathlib import Path
ROOT=Path.cwd()
lines=['[gd_resource type="Resource" script_class="CombatLoadoutDefinition" format=3]']
for key,name in {'loadout':'combat_loadout_definition','skill':'skill_definition','rank':'skill_rank_definition','target':'targeting_definition','executor':'tactical_executor','behavior':'skill_behavior_definition'}.items():lines.append(f'[ext_resource type="Script" path="res://scripts/data/{name}.gd" id="{key}"]')
for key,path in {'stats':'content/characters/graveshade_stats.tres','basic':'content/skills/graveshade_basic.tres','frames':'assets/private_graveshade/frames.tres'}.items():lines.append(f'[ext_resource type="Resource" path="res://{path}" id="{key}"]')
configs=[('j','Suppression Burst','burst','projectile',0,6.2,12,500,0,680,[5,7,7,7]),('k','Frag Deployment','grenade','area',.7,11,80,340,105,0,[1]*4),('l','Tactical Minefield','mines','area',0,16,65,340,78,0,[2,3,3,3]),('i','Heavy Ordnance','rocket','projectile',.45,28,260,650,145,460,[1,3,3])]
for slot,(key,title,move,kind,windup,cd,damage,reach,radius,speed,counts) in enumerate(configs,1):
 lines.extend([f'[sub_resource type="Resource" id="exec_{key}"]','script = ExtResource("executor")',f'executor_id = &"executor.tactical.{move}"',f'move = "{move}"',f'kind = "{kind}"',f'windup = {float(windup)}',f'firing_socket = Vector2({[32,8,0,34][slot-1]},{[-38,-30,-12,-42][slot-1]})'])
 for i,count in enumerate(counts):
  lines.extend([f'[sub_resource type="Resource" id="behavior_{key}{i}"]','script = ExtResource("behavior")','can_crit = '+str(key=='j').lower(),f'[sub_resource type="Resource" id="rank_{key}{i}"]','script = ExtResource("rank")',f'rank = {i+1}',f'cooldown = {float(cd)}',f'damage = {float(damage)}','damage_type = "PHYSICAL"',f'range_px = {float(reach)}',f'radius_px = {float(radius*(1.2 if key=="k" and i>=1 else 1))}',f'projectile_speed = {float(speed)}',f'projectile_count = {count}',f'behavior = SubResource("behavior_{key}{i}")'])
 lines.extend([f'[sub_resource type="Resource" id="target_{key}"]','script = ExtResource("target")','policy = "cursor"',f'acquisition_radius = {float(reach)}'])
 if key=="k":lines.append('prefer_nearest_with_facing_fallback = true')
 caps=['damage','on_hit_hook','on_kill_hook','cooldown_manage','repeat_cast']
 if key=='j':caps+=['modify_projectile_angle','spawn_projectile_pattern','modify_projectile_count','pierce_hit','projectile_steering']
 else:caps+=['resize_area']
 if key=='l':caps+=['apply_status']
 lines.extend([f'[sub_resource type="Resource" id="skill_{key}"]','script = ExtResource("skill")',f'id = &"skill.graveshade.{key}"',f'display_name = "{title}"',f'slot = {slot}',f'unlock_level = {[3,6,9,11][slot-1]}',f'max_rank = {len(counts)}',f'executor = SubResource("exec_{key}")',f'targeting = SubResource("target_{key}")','rank_scaling = Array[ExtResource("rank")](['+','.join(f'SubResource("rank_{key}{i}")' for i in range(len(counts)))+'])','tags = Array[StringName]([&"damage",&"physical",&"'+('projectile' if key=='j' else 'area')+'"])','declared_capabilities = Array[StringName](['+','.join('&"'+c+'"' for c in caps)+'])'])
lines.extend(['[resource]','script = ExtResource("loadout")','id = &"loadout.graveshade"','character_id = &"character.graveshade"','display_name = "Graveshade - Tactical Suppressor"','class_id = &"adc"','stats = ExtResource("stats")','basic_attack = ExtResource("basic")','art_frames = ExtResource("frames")','cast_origin_offset = Vector2(0,-27)','tint = Color(1,0.72,0.25,1)','active_skills = Array[ExtResource("skill")](['+','.join(f'SubResource("skill_{key}")' for key in 'jkli')+'])'])
(ROOT/'content/characters/graveshade_loadout.tres').write_text('\n'.join(lines)+'\n')
t=(ROOT/'content/characters/vex_stats.tres').read_text().replace('150.0','115.0').replace('270.0','210.0').replace('crit_chance = 0.1','crit_chance = 0.05');(ROOT/'content/characters/graveshade_stats.tres').write_text(t)
t=(ROOT/'content/skills/astra_basic.tres').read_text().replace('astra','graveshade').replace('Astra basic','Tactical Round').replace('basic_attack_executor_definition.gd','socket_projectile_basic.gd').replace('0.82','0.36').replace('14.0','15.0').replace('420.0','340.0').replace('650.0','680.0').replace('"MAGIC"','"PHYSICAL"');(ROOT/'content/skills/graveshade_basic.tres').write_text(t)
p=ROOT/'content/catalog.tres';t=p.read_text();t=t if 'id="graveshade"' in t else t.replace('[sub_resource','[ext_resource type="Resource" path="res://content/characters/graveshade_loadout.tres" id="graveshade"]\n\n[sub_resource',1).replace('definitions = Array[ExtResource("2")]([','definitions = Array[ExtResource("2")]([ExtResource("graveshade"), ',1);p.write_text(t)
p=ROOT/'export_presets.cfg';t=p.read_text();t=t if 'assets/private_graveshade/*.json' in t else t.replace('assets/private_viridian/*.json','assets/private_graveshade/*.json,assets/private_graveshade/audio/*.json,assets/private_viridian/*.json');p.write_text(t)
